// McpServiceServer is the server API for McpService service.
// All implementations must embed UnimplementedMcpServiceServer
// for forward compatibility.
//
// McpService holds the state and decisions of the MCP layer (api-gateway
// <-> mcp-service internal surface; NOT the MCP wire protocol). tenant_id,
// user_id and role travel in gRPC metadata (common/tenant), never in
// request bodies. RPC groups for sessions, grants, policies, approvals and
// external servers are added by their owning solutions (BE-MCP-SOL-004..014);
// only RPCs with a real implementation are declared here.
// See specs/backend-go/crs/v5/mcp-service-foundation/solutions/BE-MCP-SOL-001-scaffold-mcp-service.md.
type McpServiceServer interface {
	// GetServerInfo returns the calling tenant's MCP settings (creating the
	// default row lazily on first call) and the supported scope catalog.
	GetServerInfo(context.Context, *GetServerInfoRequest) (*GetServerInfoResponse, error)
	// CreateConsentRequest is called by GET /oauth/authorize after the cookie
	// session is valid. It re-validates the authorize parameters against
	// auth-service (never trusts caller-supplied client data), then either
	// auto-approves (redirect_url set) or stores a consent request (request_id set).
	CreateConsentRequest(context.Context, *CreateConsentRequestRequest) (*CreateConsentRequestResponse, error)
	// GetConsentRequest: only the requesting user of the same tenant sees it.
	GetConsentRequest(context.Context, *GetConsentRequestRequest) (*ConsentRequestView, error)
	DecideConsent(context.Context, *DecideConsentRequest) (*DecideConsentResponse, error)
	// ListGrants with all_users=false returns the caller's own grants;
	// all_users=true requires role admin (MCP_NOT_ADMIN) and may filter by user_id.
	ListGrants(context.Context, *ListGrantsRequest) (*ListGrantsResponse, error)
	// RevokeGrant with admin=false: caller's own grants only; admin=true requires role admin.
	// A grant that is not visible to the caller yields MCP_NOT_FOUND.
	RevokeGrant(context.Context, *RevokeGrantRequest) (*RevokeGrantResponse, error)
	// Admin-only (role admin, else MCP_NOT_ADMIN).
	ListOAuthClients(context.Context, *emptypb.Empty) (*ListOAuthClientsResponse, error)
	SetOAuthClientStatus(context.Context, *SetOAuthClientStatusRequest) (*OAuthClient, error)
	// EvaluateToolCall is the pure policy decision (no side effects). Gateway-only.
	EvaluateToolCall(context.Context, *EvaluateToolCallRequest) (*PolicyDecision, error)
	// FilterTools evaluates many tools against one snapshot (tools/list). Gateway-only.
	FilterTools(context.Context, *FilterToolsRequest) (*FilterToolsResponse, error)
	// ExplainPolicy: admin only; runs EvaluateToolCall with dry_run semantics.
	ExplainPolicy(context.Context, *ExplainPolicyRequest) (*PolicyDecision, error)
	ListToolPolicies(context.Context, *emptypb.Empty) (*ListToolPoliciesResponse, error)
	UpsertToolPolicy(context.Context, *UpsertToolPolicyRequest) (*ToolPolicy, error)
	DeleteToolPolicy(context.Context, *DeleteToolPolicyRequest) (*DeleteToolPolicyResponse, error)
	GetTenantSettings(context.Context, *emptypb.Empty) (*TenantSettings, error)
	UpdateTenantSettings(context.Context, *UpdateTenantSettingsRequest) (*TenantSettings, error)
	// AuthorizeToolCall runs the full gate: kill state, policy, egress guard,
	// paramsHash, approval create/consume, rate limit, journal. Gateway-only.
	AuthorizeToolCall(context.Context, *AuthorizeToolCallRequest) (*AuthorizeToolCallResponse, error)
	// CompleteToolCall finalizes the journal row, records taint, emits audit. Gateway-only.
	CompleteToolCall(context.Context, *CompleteToolCallRequest) (*CompleteToolCallResponse, error)
	// WaitApproval blocks until the approval leaves "pending" or max_wait_ms
	// elapses. It never consumes the approval. Gateway-only.
	WaitApproval(context.Context, *WaitApprovalRequest) (*WaitApprovalResponse, error)
	ListApprovals(context.Context, *ListApprovalsRequest) (*ListApprovalsResponse, error)
	// DecideApproval: only the approval's owner (metadata user_id) may decide;
	// anything else is MCP_NOT_FOUND. Gateway-only (cookie-session channel).
	DecideApproval(context.Context, *DecideApprovalRequest) (*Approval, error)
	SetKillSwitch(context.Context, *SetKillSwitchRequest) (*emptypb.Empty, error)
	ListKillSwitches(context.Context, *emptypb.Empty) (*ListKillSwitchesResponse, error)
	// GetKillState answers whether a request in this scope is blocked. Gateway-only.
	GetKillState(context.Context, *GetKillStateRequest) (*GetKillStateResponse, error)
	// StreamEvents streams McpEvents visible to the metadata user (owner-only
	// approval events; tenant-wide kill switch changes). Max 5 streams per user.
	StreamEvents(*emptypb.Empty, grpc.ServerStreamingServer[McpEvent]) error
	// --- MCP sessions & SSE stream registry (BE-MCP-SOL-004) ---
	// All gateway-only. tenant_id/user_id/role come from gRPC metadata. Errors:
	// MCP_NOT_FOUND (unknown/closed/foreign), MCP_STREAM_LIMIT (FailedPrecondition).
	// CreateSession stores only SHA-256(Mcp-Session-Id); the secret never reaches the DB.
	CreateSession(context.Context, *CreateSessionRequest) (*McpSession, error)
	// GetSessionBySecret returns closed sessions too (state=closed) so the gateway can answer 404.
	GetSessionBySecret(context.Context, *GetSessionBySecretRequest) (*McpSession, error)
	TouchSession(context.Context, *TouchSessionRequest) (*TouchSessionResponse, error)
	// CloseSession by row id (user: own sessions only; admin: any in tenant) or by secret_hash.
	CloseSession(context.Context, *CloseSessionRequest) (*CloseSessionResponse, error)
	// ListSessions: the metadata user's open sessions. ListSessionsAdmin: whole tenant (admin).
	ListSessions(context.Context, *ListSessionsRequest) (*ListSessionsResponse, error)
	ListSessionsAdmin(context.Context, *ListSessionsRequest) (*ListSessionsResponse, error)
	OpenStream(context.Context, *OpenStreamRequest) (*OpenStreamResponse, error)
	HeartbeatStream(context.Context, *HeartbeatStreamRequest) (*HeartbeatStreamResponse, error)
	CloseStream(context.Context, *CloseStreamRequest) (*CloseStreamResponse, error)
	// ListPrompts returns the caller's tenant prompts (any role: prompts/list on
	// /mcp needs them; the admin-only gate is the gateway channel).
	ListPrompts(context.Context, *ListPromptsRequest) (*ListPromptsResponse, error)
	// UpsertPrompt is admin-only. Empty prompt.id creates; otherwise
	// prompt.version must equal the stored version (optimistic concurrency).
	UpsertPrompt(context.Context, *UpsertPromptRequest) (*CustomPrompt, error)
	// DeletePrompt is admin-only and soft-deletes (the name becomes reusable).
	DeletePrompt(context.Context, *DeletePromptRequest) (*emptypb.Empty, error)
	mustEmbedUnimplementedMcpServiceServer()
}

